CREATE OR REPLACE FUNCTION public.icash_seller_identity_opener(p_principal text, p_address text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare body text;
begin
 if nullif(trim(p_principal),'') is null or nullif(trim(p_address),'') is null then return null;end if;
 body:='Hi, contacting you for '||trim(p_principal)||' about a cash offer. Do you own '||trim(p_address)||'? Reply STOP to opt out.';
 if length(body)>160 or body ~ '[^A-Za-z0-9 .,!?]' then return null;end if;
 return body;
end $function$

CREATE OR REPLACE FUNCTION public.icash_sms_single_segment(p_body text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare ch text;units integer:=0;basic text:=E'@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !"#¤%&''()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà';extended text:=E'\f^{}\\[~]|€';
begin
 for ch in select regexp_split_to_table(p_body,'') loop
  if position(ch in basic)>0 then units:=units+1;
  elsif position(ch in extended)>0 then units:=units+2;
  else return (select coalesce(sum(case when ascii(c)>65535 then 2 else 1 end),0)<=70 from regexp_split_to_table(p_body,'') c);end if;
 end loop;
 return units<=160;
end $function$

CREATE OR REPLACE FUNCTION public.icash_observe_seller_opener()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sent_at timestamptz;first_reply timestamptz;declined boolean;
begin
 if new.direction='outgoing' then
  update public.icash_seller_opener_assignments set message_id=new.id,
   delivered_at=case when new.state='delivered' then coalesce(delivered_at,new.last_delivery_at,now()) else delivered_at end
  where thread_id=new.thread_id and account_id=new.account_id and body=new.body and (message_id is null or message_id=new.id);
  if new.state='delivered' then
   -- The provider confirmed this send succeeded. Replies after send creation can
   -- precede the delivery webhook; keep their actual timestamps, never synthesize one.
   select min(m.created_at),coalesce(bool_or(m.body ~* '(^\s*(stop|unsubscribe|cancel|end|quit)\s*$|do not (text|contact)|don''t (text|contact)|not interested)'),false)
    into first_reply,declined from public.icash_text_messages m
    where m.thread_id=new.thread_id and m.account_id=new.account_id and m.direction='incoming' and m.state='received' and m.created_at>=new.created_at;
   update public.icash_seller_opener_assignments set first_reply_at=case when first_reply is null then first_reply_at else least(first_reply_at,first_reply) end,opted_out=opted_out or declined
    where message_id=new.id and account_id=new.account_id;
  end if;
 elsif new.direction='incoming' and new.state='received' then
  select m.created_at into sent_at from public.icash_seller_opener_assignments a join public.icash_text_messages m on m.id=a.message_id and m.account_id=a.account_id
   where a.thread_id=new.thread_id and a.account_id=new.account_id and a.delivered_at is not null;
  if sent_at is not null and new.created_at>=sent_at then
   update public.icash_seller_opener_assignments set first_reply_at=least(first_reply_at,new.created_at),opted_out=opted_out or new.body ~* '(^\s*(stop|unsubscribe|cancel|end|quit)\s*$|do not (text|contact)|don''t (text|contact)|not interested)'
    where thread_id=new.thread_id and account_id=new.account_id;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_sms_message_route()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;r public.icash_sms_routes;v jsonb;pair_sender text;pair_recipient text;
begin
 if TG_OP='UPDATE' then
  if row(new.thread_id,new.account_id,new.direction,new.route_revision) is distinct from row(old.thread_id,old.account_id,old.direction,old.route_revision) then
   if not (old.thread_id is null and new.thread_id is not null and old.state='needs_review' and new.state='received'
    and row(new.account_id,new.direction,new.route_revision,new.body,new.created_at,new.event_id,new.provider_id,new.attachments)
      is not distinct from row(old.account_id,old.direction,old.route_revision,old.body,old.created_at,old.event_id,old.provider_id,old.attachments)
    and public.icash_sms_owner_reply_resolution_current(old.id,new.account_id,new.thread_id,new.route_revision))
   then raise exception 'SMS message route is immutable';end if;
  end if;
  return new;
 end if;
 -- Provider retries and repeated queue requests must not advance routing state.
 if exists(select 1 from public.icash_text_messages m where (new.event_id is not null and m.event_id=new.event_id) or (new.provider_id is not null and m.provider_id=new.provider_id) or (new.request_key is not null and m.request_key=new.request_key)) then return null;end if;
 if new.thread_id is not null then
 select * into t from public.icash_text_threads where id=new.thread_id and account_id=new.account_id;
 if not found then raise exception 'SMS message account mismatch';end if;
 pair_sender:=t.sender;pair_recipient:=t.recipient;
 elsif new.direction='incoming' then
 select payload->'data' into v from public.icash_text_events where id=new.event_id;
 pair_sender:=v->>'to';pair_recipient:=v->>'from';
 end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform pg_advisory_xact_lock(hashtextextended(pair_recipient,74));
 select * into r from public.icash_sms_routes where sender=pair_sender and recipient=pair_recipient for update;
 if new.direction='outgoing' then
  if r.account_id is distinct from new.account_id or (r.needs_review and not public.icash_seller_clarification_current(new.account_id,new.thread_id,new.request_key,new.body,r.revision) and not (cardinality(new.asset_ids)=0 and new.attachments='[]'::jsonb and public.icash_fresh_intake_opener_current(new.account_id,new.thread_id,new.request_key,new.body,r.revision))) or t.retired_at is not null then raise exception 'SMS property routing requires review';end if;
 elsif r.account_id is not null then
  -- Any incoming message invalidates queued decisions; ambiguous replies hold all
  -- properties on the pair until an explicit property reply or human review.
  update public.icash_sms_routes set revision=revision+1,needs_review=(new.thread_id is null) where sender=pair_sender and recipient=pair_recipient returning * into r;
  if new.thread_id is null then new.account_id:=r.account_id;new.state:='needs_review';end if;
 end if;
 new.route_revision:=r.revision;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_text_before_owner_question(p_account uuid, p_message uuid, p_sender text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare invitation public.icash_sms_inbound_invitations;t public.icash_text_threads;m public.icash_text_messages;d public.icash_deal_files;s public.icash_screening_jobs;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select th.* into t from public.icash_text_threads th join public.icash_text_messages msg on msg.thread_id=th.id and msg.account_id=th.account_id where msg.id=p_message and msg.account_id=p_account;
 if not found then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(t.recipient,74));
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;if not found then return null;end if;
 perform 1 from public.icash_outreach_campaigns where account_id=p_account for share;
 select * into t from public.icash_text_threads where id=t.id and account_id=p_account for update;
 select * into m from public.icash_text_messages where id=p_message and account_id=p_account and thread_id=t.id for update;
 if not found or m.state<>'ready' or m.direction<>'outgoing' then return null;end if;
 select * into d from public.icash_deal_files where id=t.deal_id and account_id=p_account and stage not in ('closed','cancelled') and coalesce(terms->>'practice','false')<>'true' for share;
 if not found then return null;end if;
 select * into s from public.icash_screening_jobs where id=d.screening_id and account_id=p_account and state='complete' for share;
 if not found then return null;end if;
 if t.party='buyer' then
  if public.icash_buyer_package_data(p_account,d.id) is null then return null;end if;
 else if not public.icash_customer_authored_text(p_account,p_message) and not public.icash_seller_recovery_nonprice_current(p_account,p_message) and not (exists(select 1 from public.icash_text_ai_jobs where account_id=p_account and outgoing_id=p_message and analysis->>'offerPolicy'='seller-text-offer-v1') and public.icash_seller_conversation_message_current(p_account,p_message)) and not (public.icash_seller_limited_contact(p_account,s.id) and (exists(select 1 from public.icash_sms_seller_openings opening where opening.thread_id=t.id and opening.owner_question_id=m.id) or m.body='Are there any mortgages, liens, or unpaid taxes that would need to be paid at closing?' or public.icash_limited_seller_text_current(p_account,p_message))) and (s.result->'financialCheck'->>'status' is distinct from 'eligible' or s.completed_at is null or s.completed_at>now() or s.completed_at<now()-interval '24 hours') then return null;end if; end if;

 if exists(select 1 from public.icash_property_controls where account_id=p_account and property_id=s.snapshot->>'propertyId' and manual)
 and not (
  (public.icash_manual_handoff_reply(p_account,t.id) or public.icash_customer_authored_text(p_account,p_message))
  and not exists(select 1 from public.icash_text_ai_jobs where outgoing_id=p_message and account_id=p_account)
  and not exists(select 1 from public.icash_seller_opener_assignments where message_id=p_message and account_id=p_account)
  and not exists(select 1 from public.icash_sms_inbound_invitations where message_id=p_message and account_id=p_account)
 ) then return null;end if;
 if exists(select 1 from public.icash_text_ai_jobs where outgoing_id=p_message and account_id=p_account) and not public.icash_seller_conversation_message_current(p_account,p_message)
 and not exists(select 1 from public.icash_text_ai_jobs j join public.icash_text_messages incoming on incoming.id=j.message_id and incoming.account_id=j.account_id and incoming.thread_id=j.thread_id
 where j.account_id=p_account and j.thread_id=t.id and j.outgoing_id=p_message and j.state='queued'
 and t.party='buyer' and t.ai_mode='auto' and not t.paused and t.retired_at is null
 and j.analysis->>'action'='buyer_factual' and j.analysis->>'factualPolicy'='approved-package-v1'
 and incoming.direction='incoming' and incoming.state='received'
 and m.body=public.icash_buyer_factual_text(p_account,t.id,incoming.body)) then return null;end if;
 if t.dnc_checked_at>now() then return null;end if;
 if not public.icash_sms_thread_review_current(p_account,t.id,true) then return null;end if;
 if not public.icash_outreach_sms_current(p_account) then return null;end if;
 select * into invitation from public.icash_sms_inbound_invitations where message_id=p_message and account_id=p_account;
 if found then
  if not public.icash_sms_inbound_campaign_current(p_account) then return null;end if;
  select * into t from public.icash_text_threads where id=invitation.thread_id and account_id=p_account;
  if t.id is null or t.sender<>invitation.sender or t.recipient<>invitation.recipient or t.deal_id<>invitation.deal_id or invitation.expires_at<=now() then return null;end if;
  if not exists(select 1 from public.icash_inbound_voice_routes where called_number=invitation.called_number and business_number=p_sender and enabled and reviewed_until>now() and agent_config_hash is not null) then return null;end if;
  if exists(select 1 from public.icash_text_messages where thread_id=t.id and direction='incoming' and id<>invitation.reply_id and created_at>=(select created_at from public.icash_text_messages where id=invitation.reply_id)) then return null;end if;
 end if;
 return public.icash_claim_text_before_campaign(p_account,p_message,p_sender);
end $function$
